1	import React, { useId } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
4	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
5	import { useUiCopy } from 'app/hooks/useUiCopy';
6	
7	const ZIMM_COUNTRY_LANGUAGE_MISMATCH_RECIPE = 'ZimmCountryLanguageMismatch';
8	
9	type ZimmCountryLanguageMismatchBaseProps = {
10	  /** Whether the prompt is open. Forwarded straight to `ZimmDrawer`. */
11	  isOpen: boolean;
12	  /**
13	   * Fires on every close path — backdrop click, close X, Esc (all three arrive via
14	   * `ZimmDrawer`'s own `onClose`, wired straight to this) — **and** the "stay" CTA's own
15	   * `onClick`. Always a direct, synchronous call from the interaction handler, never deferred to
16	   * `ZimmDrawer`'s `onCloseComplete`/exit-animation callback: the consumer writes a suppression
17	   * cookie inside `onDismiss` before performing a hard `window.location =` navigation elsewhere
18	   * in the flow, and a deferred callback risks losing that write to a fast subsequent page unload.
19	   */
20	  onDismiss: () => void;
21	};
22	
23	export type ZimmCountryLanguageMismatchLocationProps = ZimmCountryLanguageMismatchBaseProps & {
24	  variant: 'location';
25	  inCountry: string;
26	  currentStore: string;
27	  targetStore: string;
28	  /**
29	   * Opaque target identifier — a site alias, a locale string, whatever the consumer's own
30	   * eligibility logic resolved. Never read or interpreted by this component; only ever handed
31	   * back, unmodified, to `onRedirect` when the act CTA fires.
32	   */
33	  target: unknown;
34	  onRedirect: (target: unknown) => void;
35	};
36	
37	export type ZimmCountryLanguageMismatchLanguageProps = ZimmCountryLanguageMismatchBaseProps & {
38	  variant: 'language';
39	  inCountry: string;
40	  inLanguage: string;
41	  inCurrentLanguage: string;
42	  /** Same treatment as `ZimmCountryLanguageMismatchLocationProps['target']` — opaque, echoed
43	   *  back unmodified to `onSwitchLanguage`. */
44	  target: unknown;
45	  onSwitchLanguage: (target: unknown) => void;
46	};
47	
48	export type ZimmCountryLanguageMismatchProps =
49	  | ZimmCountryLanguageMismatchLocationProps
50	  | ZimmCountryLanguageMismatchLanguageProps;
51	
52	type ZimmCountryLanguageMismatchVariant = ZimmCountryLanguageMismatchProps['variant'];
53	
54	/**
55	 * Widened, not narrowed — same technique and reason as `zimmProductCard/index.tsx`'s own
56	 * `ZimmProductCardVariationFields` (see that file's comment in full): every variant-specific
57	 * field is optional here purely so the render body below can destructure once with no
58	 * `if`/`switch` on `props.variant`. The exported discriminated union above is what actually
59	 * enforces correct usage at every call site — this cast only relaxes internal access inside this
60	 * file; it changes nothing about what a caller may legally pass in.
61	 */
62	type ZimmCountryLanguageMismatchVariationFields = Partial<
63	  Omit<ZimmCountryLanguageMismatchLocationProps, keyof ZimmCountryLanguageMismatchBaseProps | 'variant' | 'target'> &
64	    Omit<ZimmCountryLanguageMismatchLanguageProps, keyof ZimmCountryLanguageMismatchBaseProps | 'variant' | 'target'>
65	>;
66	
67	type ZimmCountryLanguageMismatchConfig = {
68	  headingKey: string;
69	  headingFallback: string;
70	  bodyKey: string;
71	  bodyFallback: string;
72	  switchCtaKey: string;
73	  switchCtaFallback: string;
74	  stayCtaKey: string;
75	  stayCtaFallback: string;
76	};
77	
78	/**
79	 * The extensibility mechanism this component is built around — every piece of copy that differs
80	 * between `location` and `language` comes from indexing into this table by `variant`, the same
81	 * technique `zimmProductCard/index.tsx`'s own `VARIATION_CONFIG` (line 316) uses for its
82	 * layout/visibility decisions. Zero `switch`/`if` on `props.variant` anywhere below (verified via
83	 * `grep -n "variant ===\|switch (variant)" index.tsx` — zero hits).
84	 *
85	 * Copy keys and English fallbacks are frozen by SFCC-831's decision record — do not invent new
86	 * ones. Sentence case throughout, never caps: `textStyle="heading3"` already carries
87	 * `textTransform: uppercase` (theme/foundation/typography.ts), so a capitalised fallback here
88	 * would double-transform.
89	 */
90	const VARIATION_CONFIG: Record<ZimmCountryLanguageMismatchVariant, ZimmCountryLanguageMismatchConfig> = {
91	  location: {
92	    headingKey: 'regional.locationPrompt.heading',
93	    headingFallback: "Looks like you're {inCountry}",
94	    bodyKey: 'regional.locationPrompt.body',
95	    bodyFallback:
96	      "You're currently shopping on {currentStore}. Switch to {targetStore} for local pricing, currency and shipping options.",
97	    switchCtaKey: 'regional.locationPrompt.cta.switch',
98	    switchCtaFallback: 'Switch to {targetStore}',
99	    stayCtaKey: 'regional.locationPrompt.cta.stay',
100	    stayCtaFallback: 'Stay on {currentStore}',
101	  },
102	  language: {
103	    headingKey: 'regional.languagePrompt.heading',
104	    headingFallback: 'Welcome to Zimmermann Europe',
105	    bodyKey: 'regional.languagePrompt.body',
106	    bodyFallback:
107	      "Welcome to Zimmermann Europe. We noticed you're {inCountry}, would you like to view our site {inLanguage}?",
108	    switchCtaKey: 'regional.languagePrompt.cta.switch',
109	    switchCtaFallback: 'View {inLanguage}',
110	    stayCtaKey: 'regional.languagePrompt.cta.stay',
111	    stayCtaFallback: 'Continue {inCurrentLanguage}',
112	  },
113	};
114	
115	/**
116	 * Strips undefined entries so the cross-variant prop bag satisfies `useUiCopy`'s `t()` values
117	 * shape (`Record<string, string | number>` — no `undefined`). Safe to merge every display field
118	 * from both variants unconditionally: each `VARIATION_CONFIG` fallback above only ever
119	 * references the `{token}` names that exist for its own variant, so a field left undefined by
120	 * the *other* variant is simply never looked up by `interpolateUiCopy` (useUiCopy.ts).
121	 */
122	const definedValues = (values: Record<string, string | undefined>): Record<string, string> =>
123	  Object.fromEntries(Object.entries(values).filter((entry): entry is [string, string] => entry[1] !== undefined));
124	
125	/**
126	 * Organism — the EU country/language mismatch prompt (SFCC-831), a modal `ZimmDrawer`
127	 * (`size="prompt"`) offering to switch storefront or language. Two variants share one component
128	 * and one layout: `location` (shopper's browser reports a different country than the current
129	 * storefront) and `language` (EU domestic storefront, browser reports a different language).
130	 * Composition modelled on `zimmWishlistAuthDrawer/index.tsx` — a drawer wrapper with no state of
131	 * its own, composing content underneath `ZimmDrawer`.
132	 *
133	 * **Deliberately ignorant of sites/locales/aliases.** `target` is never read or interpreted here
134	 * — it is handed back to `onRedirect`/`onSwitchLanguage` exactly as received when the act CTA
135	 * fires. The consumer (SFCC-689) owns all site/locale/alias logic; this component only knows how
136	 * to ask the question and report which answer the shopper picked.
137	 *
138	 * Both CTAs and the close button (the close button is `ZimmDrawer`'s own, already localised —
139	 * see `zimmDrawer/index.tsx`) render as real `ZimmButton`/`<button>` elements and inherit their
140	 * hover/focus-visible/active/disabled treatment entirely from `zimmButton.css.ts`;
141	 * `zimmCountryLanguageMismatch.css.ts` authors no interaction-state rule of its own — see that
142	 * file's own comment for why (Figma defines only `Step=–`, no other state, for this component).
143	 *
144	 * @param props see `ZimmCountryLanguageMismatchProps` — a discriminated union on `variant`.
145	 */
146	export const ZimmCountryLanguageMismatch = (props: ZimmCountryLanguageMismatchProps) => {
147	  const { isOpen, onDismiss, variant, target } = props;
148	  const { inCountry, currentStore, targetStore, inLanguage, inCurrentLanguage, onRedirect, onSwitchLanguage } =
149	    props as ZimmCountryLanguageMismatchVariationFields;
150	
151	  const { t } = useUiCopy();
152	  const headingId = useId();
153	  const styles = useMultiStyleConfig(ZIMM_COUNTRY_LANGUAGE_MISMATCH_RECIPE, {});
154	  const config = VARIATION_CONFIG[variant];
155	
156	  const values = definedValues({ inCountry, currentStore, targetStore, inLanguage, inCurrentLanguage });
157	
158	  const heading = t(config.headingKey, config.headingFallback, values);
159	  const body = t(config.bodyKey, config.bodyFallback, values);
160	  const switchCta = t(config.switchCtaKey, config.switchCtaFallback, values);
161	  const stayCta = t(config.stayCtaKey, config.stayCtaFallback, values);
162	
163	  // Exactly one of these two is ever defined for a given `variant` — enforced by the exported
164	  // discriminated union, not by this file. Optional-chaining both dispatches to whichever one a
165	  // caller actually supplied, with zero branching on `variant` itself.
166	  const handleAct = (): void => {
167	    onRedirect?.(target);
168	    onSwitchLanguage?.(target);
169	  };
170	
171	  return (
172	    <ZimmDrawer isOpen={isOpen} onClose={onDismiss} size="prompt" labelledBy={headingId} boxedHeader>
173	      <chakra.div __css={styles.root}>
174	        <chakra.div __css={styles.content}>
175	          <chakra.h2 id={headingId} textStyle="heading3" color="var(--zimm-color-text-default)" margin={0}>
176	            {heading}
177	          </chakra.h2>
178	          <chakra.p textStyle="body2" color="var(--zimm-color-text-default)" margin={0}>
179	            {body}
180	          </chakra.p>
181	        </chakra.div>
182	        <chakra.div __css={styles.buttonGroup}>
183	          <ZimmButton variant="secondary" size="adaptive" fullWidth label={switchCta} onClick={handleAct} />
184	          <ZimmButton variant="primary" size="adaptive" fullWidth label={stayCta} onClick={onDismiss} />
185	        </chakra.div>
186	      </chakra.div>
187	    </ZimmDrawer>
188	  );
189	};
190	
191	export default ZimmCountryLanguageMismatch;
