import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ZimmWishlistAuthDrawer } from './index';
import { useWishlistAuthDrawer } from 'app/hooks/useWishlistAuthDrawer';
import type { UseWishlistAuthDrawerReturn } from 'app/hooks/useWishlistAuthDrawer';

// ZimmDrawer's recipe (zimmDrawer.css.ts) has its own test coverage as of SFCC-831
// (zimmDrawer.css.test.ts); the component itself (index.tsx) has no index.test.tsx yet. Mock it
// to a minimal dialog stub regardless, so this suite can assert on open/close state without a
// full Chakra portal environment.
vi.mock('app/components/ui-kits/atoms/zimmDrawer', () => ({
  ZimmDrawer: ({
    isOpen,
    onClose,
    children,
  }: {
    isOpen: boolean;
    onClose: () => void;
    children: React.ReactNode;
  }) =>
    isOpen ? (
      <div role="dialog">
        <button onClick={onClose}>Close</button>
        {children}
      </div>
    ) : null,
}));

// ZimmAuthDrawerContent's contract is covered by its own test file.
vi.mock('app/components/ui-kits/organisms/zimmAuthDrawerContent', () => ({
  ZimmAuthDrawerContent: () => <div data-testid="auth-drawer-content" />,
}));

// OtpAuth and AuthModal are SFCC base components — stub shapes only.
vi.mock('@salesforce/retail-react-app/app/components/otp-auth', () => ({
  default: ({ isOpen }: { isOpen: boolean }) =>
    isOpen ? <div data-testid="otp-auth" /> : null,
}));
vi.mock('@salesforce/retail-react-app/app/hooks/use-auth-modal', () => ({
  AuthModal: () => null,
}));

// All auth logic is in the hook — mock it to control state per test.
// A factory is required; without one, Vitest auto-imports the real module which pulls in
// SFCC's JSX contexts barrel and breaks the transform.
vi.mock('app/hooks/useWishlistAuthDrawer', () => ({
  useWishlistAuthDrawer: vi.fn(),
}));

const mockUseWishlistAuthDrawer = vi.mocked(useWishlistAuthDrawer);

function makeDefaultReturn(overrides: Partial<UseWishlistAuthDrawerReturn> = {}): UseWishlistAuthDrawerReturn {
  return {
    isOpen: false,
    handleDrawerClose: vi.fn(),
    handleTriggerClick: vi.fn(),
    triggerRef: { current: null },
    drawerTitle: 'Wishlist',
    description: 'You must log in or create an account to add items to your wishlist.',
    emailValue: '',
    onEmailChange: vi.fn(),
    onSendCode: vi.fn(),
    onSignInWithApple: undefined,
    onSignInWithGoogle: undefined,
    isSocialEnabled: false,
    isPasswordlessEnabled: true,
    emailInputRef: { current: null },
    socialError: undefined,
    onCreateAccount: vi.fn(),
    isOtpAuthOpen: false,
    onOtpAuthClose: vi.fn(),
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    form: {} as any,
    handlePasswordlessLogin: vi.fn().mockResolvedValue({ success: true }),
    handleOtpVerification: vi.fn().mockResolvedValue({ success: true }),
    registerModal: { isOpen: false, onOpen: vi.fn(), onClose: vi.fn() } as UseWishlistAuthDrawerReturn['registerModal'],
    ...overrides,
  };
}

describe('ZimmWishlistAuthDrawer', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockUseWishlistAuthDrawer.mockReturnValue(makeDefaultReturn());
  });

  describe('trigger wiring', () => {
    test('renders the child trigger element', () => {
      render(
        <ZimmWishlistAuthDrawer intentId="test-wishlist">
          <button>Wishlist</button>
        </ZimmWishlistAuthDrawer>,
      );

      expect(screen.getByRole('button', { name: 'Wishlist' })).toBeInTheDocument();
    });

    test('clicking the trigger calls handleTriggerClick', async () => {
      const handleTriggerClick = vi.fn();
      mockUseWishlistAuthDrawer.mockReturnValue(makeDefaultReturn({ handleTriggerClick }));

      render(
        <ZimmWishlistAuthDrawer intentId="test-wishlist">
          <button>Add to wishlist</button>
        </ZimmWishlistAuthDrawer>,
      );

      await userEvent.click(screen.getByRole('button', { name: 'Add to wishlist' }));

      expect(handleTriggerClick).toHaveBeenCalledTimes(1);
    });

    test('forwards intentId and onAuthSuccess to useWishlistAuthDrawer', () => {
      const onAuthSuccess = vi.fn();
      render(
        <ZimmWishlistAuthDrawer intentId="pdp-wishlist" onAuthSuccess={onAuthSuccess}>
          <button>Wishlist</button>
        </ZimmWishlistAuthDrawer>,
      );

      expect(mockUseWishlistAuthDrawer).toHaveBeenCalledWith({ intentId: 'pdp-wishlist', onAuthSuccess });
    });
  });

  describe('drawer open state', () => {
    test('renders the drawer when isOpen is true', () => {
      mockUseWishlistAuthDrawer.mockReturnValue(makeDefaultReturn({ isOpen: true }));

      render(
        <ZimmWishlistAuthDrawer intentId="test-wishlist">
          <button>Wishlist</button>
        </ZimmWishlistAuthDrawer>,
      );

      expect(screen.getByRole('dialog')).toBeInTheDocument();
    });

    test('does not render the drawer when isOpen is false', () => {
      render(
        <ZimmWishlistAuthDrawer intentId="test-wishlist">
          <button>Wishlist</button>
        </ZimmWishlistAuthDrawer>,
      );

      expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
    });

    test('renders ZimmAuthDrawerContent inside the open drawer', () => {
      mockUseWishlistAuthDrawer.mockReturnValue(makeDefaultReturn({ isOpen: true }));

      render(
        <ZimmWishlistAuthDrawer intentId="test-wishlist">
          <button>Wishlist</button>
        </ZimmWishlistAuthDrawer>,
      );

      expect(screen.getByTestId('auth-drawer-content')).toBeInTheDocument();
    });
  });

  describe('drawer close', () => {
    test('clicking the close button calls handleDrawerClose', async () => {
      const handleDrawerClose = vi.fn();
      mockUseWishlistAuthDrawer.mockReturnValue(makeDefaultReturn({ isOpen: true, handleDrawerClose }));

      render(
        <ZimmWishlistAuthDrawer intentId="test-wishlist">
          <button>Wishlist</button>
        </ZimmWishlistAuthDrawer>,
      );

      await userEvent.click(screen.getByRole('button', { name: 'Close' }));

      expect(handleDrawerClose).toHaveBeenCalledTimes(1);
    });
  });
});

