1	import React from 'react';
2	import { describe, test, expect, vi, beforeEach } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	import userEvent from '@testing-library/user-event';
5	import { ZimmCountryLanguageMismatch } from './index';
6	import type { ZimmCountryLanguageMismatchLocationProps, ZimmCountryLanguageMismatchLanguageProps } from './index';
7	import { useUiCopy } from 'app/hooks/useUiCopy';
8	
9	// ZimmDrawer's own recipe/component have their own test coverage (zimmDrawer.css.test.ts,
10	// SFCC-831). Mock it to a minimal dialog stub so this suite can assert on open/close state and
11	// accessible-name wiring without a full Chakra portal environment — same technique
12	// zimmWishlistAuthDrawer/index.test.tsx uses for the same recipe. Forwards `labelledBy` as a
13	// real `aria-labelledby` (matching ZimmDrawerContent's own dialogProps wiring, zimmDrawer/
14	// index.tsx) so `getByRole('dialog', {name})` proves this component's own headingId plumbing,
15	// not just that *some* dialog rendered.
16	vi.mock('app/components/ui-kits/atoms/zimmDrawer', () => ({
17	  ZimmDrawer: ({
18	    isOpen,
19	    onClose,
20	    labelledBy,
21	    children,
22	  }: {
23	    isOpen: boolean;
24	    onClose: () => void;
25	    labelledBy?: string;
26	    children: React.ReactNode;
27	  }) =>
28	    isOpen ? (
29	      <div role="dialog" aria-labelledby={labelledBy}>
30	        <button onClick={onClose}>mock-close</button>
31	        {children}
32	      </div>
33	    ) : null,
34	}));
35	
36	// ZimmButton is rendered for real below (not mocked) — its own label/click contract is exactly
37	// what this suite needs to assert on. It imports ZimmIcon at module scope even though neither
38	// CTA here uses variant="icon", and ZimmIcon pulls in the base SFCC icons barrel, which throws
39	// under Vitest at import time (see .claude/rules/testing.md's "Known gap: ZimmIcon throws under
40	// Vitest"). Smallest-surface mock; no assertion below depends on icon content.
41	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
42	  ZimmIcon: () => null,
43	}));
44	
45	// useUiCopy's own fetch/lookup logic has its own test coverage (UiCopyProvider); mocking it here
46	// isolates this suite to ZimmCountryLanguageMismatch's own contract — same technique
47	// zimmSubscribeSection/index.test.tsx uses. The default mock returns the fallback unmodified:
48	// real interpolation isn't needed to prove "this variant renders its own heading/body/CTA
49	// content" (the raw fallback string, `{token}` placeholders included, is a perfectly good
50	// assertion target) — the explicit toHaveBeenCalledWith assertions below separately prove the
51	// values object each call receives.
52	vi.mock('app/hooks/useUiCopy', () => ({
53	  useUiCopy: vi.fn(),
54	}));
55	
56	const mockUseUiCopy = vi.mocked(useUiCopy);
57	const mockT = vi.fn((_key: string, fallback: string) => fallback);
58	
59	const LOCATION_HEADING_FALLBACK = "Looks like you're {inCountry}";
60	const LOCATION_BODY_FALLBACK =
61	  "You're currently shopping on {currentStore}. Switch to {targetStore} for local pricing, currency and shipping options.";
62	const LOCATION_SWITCH_CTA_FALLBACK = 'Switch to {targetStore}';
63	const LOCATION_STAY_CTA_FALLBACK = 'Stay on {currentStore}';
64	
65	const LANGUAGE_HEADING_FALLBACK = 'Welcome to Zimmermann Europe';
66	const LANGUAGE_BODY_FALLBACK =
67	  "Welcome to Zimmermann Europe. We noticed you're {inCountry}, would you like to view our site {inLanguage}?";
68	const LANGUAGE_SWITCH_CTA_FALLBACK = 'View {inLanguage}';
69	const LANGUAGE_STAY_CTA_FALLBACK = 'Continue {inCurrentLanguage}';
70	
71	function makeLocationProps(
72	  overrides: Partial<ZimmCountryLanguageMismatchLocationProps> = {},
73	): ZimmCountryLanguageMismatchLocationProps {
74	  return {
75	    variant: 'location',
76	    isOpen: true,
77	    onDismiss: vi.fn(),
78	    inCountry: 'in Germany',
79	    currentStore: 'Zimmermann Australia',
80	    targetStore: 'Zimmermann Germany',
81	    target: { siteAlias: 'ZimmermannEUde', localeAlias: 'de-DE' },
82	    onRedirect: vi.fn(),
83	    ...overrides,
84	  };
85	}
86	
87	function makeLanguageProps(
88	  overrides: Partial<ZimmCountryLanguageMismatchLanguageProps> = {},
89	): ZimmCountryLanguageMismatchLanguageProps {
90	  return {
91	    variant: 'language',
92	    isOpen: true,
93	    onDismiss: vi.fn(),
94	    inCountry: 'in France',
95	    inLanguage: 'in French',
96	    inCurrentLanguage: 'in English',
97	    target: 'fr-FR-Weird-Casing',
98	    onSwitchLanguage: vi.fn(),
99	    ...overrides,
100	  };
101	}
102	
103	describe('ZimmCountryLanguageMismatch', () => {
104	  beforeEach(() => {
105	    vi.clearAllMocks();
106	    mockT.mockImplementation((_key: string, fallback: string) => fallback);
107	    mockUseUiCopy.mockReturnValue({ t: mockT, isLoading: false });
108	  });
109	
110	  describe('location variant', () => {
111	    test('renders its own heading, body, and CTA content', () => {
112	      render(<ZimmCountryLanguageMismatch {...makeLocationProps()} />);
113	
114	      expect(screen.getByRole('heading', { name: LOCATION_HEADING_FALLBACK, level: 2 })).toBeInTheDocument();
115	      expect(screen.getByText(LOCATION_BODY_FALLBACK)).toBeInTheDocument();
116	      expect(screen.getByRole('button', { name: LOCATION_SWITCH_CTA_FALLBACK })).toBeInTheDocument();
117	      expect(screen.getByRole('button', { name: LOCATION_STAY_CTA_FALLBACK })).toBeInTheDocument();
118	    });
119	
120	    test('the dialog is labelled by the rendered heading', () => {
121	      render(<ZimmCountryLanguageMismatch {...makeLocationProps()} />);
122	
123	      expect(screen.getByRole('dialog', { name: LOCATION_HEADING_FALLBACK })).toBeInTheDocument();
124	    });
125	
126	    test('passes the location copy keys and display values to t()', () => {
127	      render(<ZimmCountryLanguageMismatch {...makeLocationProps()} />);
128	
129	      expect(mockT).toHaveBeenCalledWith(
130	        'regional.locationPrompt.heading',
131	        LOCATION_HEADING_FALLBACK,
132	        expect.objectContaining({ inCountry: 'in Germany' }),
133	      );
134	      expect(mockT).toHaveBeenCalledWith(
135	        'regional.locationPrompt.body',
136	        LOCATION_BODY_FALLBACK,
137	        expect.objectContaining({ currentStore: 'Zimmermann Australia', targetStore: 'Zimmermann Germany' }),
138	      );
139	      expect(mockT).toHaveBeenCalledWith(
140	        'regional.locationPrompt.cta.switch',
141	        LOCATION_SWITCH_CTA_FALLBACK,
142	        expect.objectContaining({ targetStore: 'Zimmermann Germany' }),
143	      );
144	      expect(mockT).toHaveBeenCalledWith(
145	        'regional.locationPrompt.cta.stay',
146	        LOCATION_STAY_CTA_FALLBACK,
147	        expect.objectContaining({ currentStore: 'Zimmermann Australia' }),
148	      );
149	    });
150	  });
151	
152	  describe('language variant', () => {
153	    test('renders its own heading, body, and CTA content', () => {
154	      render(<ZimmCountryLanguageMismatch {...makeLanguageProps()} />);
155	
156	      expect(screen.getByRole('heading', { name: LANGUAGE_HEADING_FALLBACK, level: 2 })).toBeInTheDocument();
157	      expect(screen.getByText(LANGUAGE_BODY_FALLBACK)).toBeInTheDocument();
158	      expect(screen.getByRole('button', { name: LANGUAGE_SWITCH_CTA_FALLBACK })).toBeInTheDocument();
159	      expect(screen.getByRole('button', { name: LANGUAGE_STAY_CTA_FALLBACK })).toBeInTheDocument();
160	    });
161	
162	    test('the dialog is labelled by the rendered heading', () => {
163	      render(<ZimmCountryLanguageMismatch {...makeLanguageProps()} />);
164	
165	      expect(screen.getByRole('dialog', { name: LANGUAGE_HEADING_FALLBACK })).toBeInTheDocument();
166	    });
167	
168	    test('passes the language copy keys and display values to t()', () => {
169	      render(<ZimmCountryLanguageMismatch {...makeLanguageProps()} />);
170	
171	      expect(mockT).toHaveBeenCalledWith(
172	        'regional.languagePrompt.heading',
173	        LANGUAGE_HEADING_FALLBACK,
174	        expect.objectContaining({ inCountry: 'in France' }),
175	      );
176	      expect(mockT).toHaveBeenCalledWith(
177	        'regional.languagePrompt.body',
178	        LANGUAGE_BODY_FALLBACK,
179	        expect.objectContaining({ inCountry: 'in France', inLanguage: 'in French' }),
180	      );
181	      expect(mockT).toHaveBeenCalledWith(
182	        'regional.languagePrompt.cta.switch',
183	        LANGUAGE_SWITCH_CTA_FALLBACK,
184	        expect.objectContaining({ inLanguage: 'in French' }),
185	      );
186	      expect(mockT).toHaveBeenCalledWith(
187	        'regional.languagePrompt.cta.stay',
188	        LANGUAGE_STAY_CTA_FALLBACK,
189	        expect.objectContaining({ inCurrentLanguage: 'in English' }),
190	      );
191	    });
192	  });
193	
194	  describe('dismiss wiring', () => {
195	    test('onDismiss fires when the drawer reports close (backdrop/X/Esc, via ZimmDrawer onClose)', async () => {
196	      const onDismiss = vi.fn();
197	      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ onDismiss })} />);
198	
199	      await userEvent.click(screen.getByRole('button', { name: 'mock-close' }));
200	
201	      expect(onDismiss).toHaveBeenCalledTimes(1);
202	    });
203	
204	    test('onDismiss fires when the stay CTA is clicked', async () => {
205	      const onDismiss = vi.fn();
206	      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ onDismiss })} />);
207	
208	      await userEvent.click(screen.getByRole('button', { name: LOCATION_STAY_CTA_FALLBACK }));
209	
210	      expect(onDismiss).toHaveBeenCalledTimes(1);
211	    });
212	
213	    test('the stay CTA does not also fire onRedirect', async () => {
214	      const onDismiss = vi.fn();
215	      const onRedirect = vi.fn();
216	      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ onDismiss, onRedirect })} />);
217	
218	      await userEvent.click(screen.getByRole('button', { name: LOCATION_STAY_CTA_FALLBACK }));
219	
220	      expect(onDismiss).toHaveBeenCalledTimes(1);
221	      expect(onRedirect).not.toHaveBeenCalled();
222	    });
223	  });
224	
225	  describe('act-CTA callback wiring', () => {
226	    test('onRedirect fires with the exact target value, unmodified', async () => {
227	      const target = { siteAlias: 'ZimmermannEUde', localeAlias: 'de-DE' };
228	      const onRedirect = vi.fn();
229	      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ target, onRedirect })} />);
230	
231	      await userEvent.click(screen.getByRole('button', { name: LOCATION_SWITCH_CTA_FALLBACK }));
232	
