import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ZimmCountryLanguageMismatch } from './index';
import type { ZimmCountryLanguageMismatchLocationProps, ZimmCountryLanguageMismatchLanguageProps } from './index';
import { useUiCopy } from 'app/hooks/useUiCopy';

// ZimmDrawer's own recipe/component have their own test coverage (zimmDrawer.css.test.ts,
// SFCC-831). Mock it to a minimal dialog stub so this suite can assert on open/close state and
// accessible-name wiring without a full Chakra portal environment — same technique
// zimmWishlistAuthDrawer/index.test.tsx uses for the same recipe. Forwards `labelledBy` as a
// real `aria-labelledby` (matching ZimmDrawerContent's own dialogProps wiring, zimmDrawer/
// index.tsx) so `getByRole('dialog', {name})` proves this component's own headingId plumbing,
// not just that *some* dialog rendered.
vi.mock('app/components/ui-kits/atoms/zimmDrawer', () => ({
  ZimmDrawer: ({
    isOpen,
    onClose,
    labelledBy,
    children,
  }: {
    isOpen: boolean;
    onClose: () => void;
    labelledBy?: string;
    children: React.ReactNode;
  }) =>
    isOpen ? (
      <div role="dialog" aria-labelledby={labelledBy}>
        <button onClick={onClose}>mock-close</button>
        {children}
      </div>
    ) : null,
}));

// ZimmButton is rendered for real below (not mocked) — its own label/click contract is exactly
// what this suite needs to assert on. It imports ZimmIcon at module scope even though neither
// CTA here uses variant="icon", and ZimmIcon pulls in the base SFCC icons barrel, which throws
// under Vitest at import time (see .claude/rules/testing.md's "Known gap: ZimmIcon throws under
// Vitest"). Smallest-surface mock; no assertion below depends on icon content.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

// useUiCopy's own fetch/lookup logic has its own test coverage (UiCopyProvider); mocking it here
// isolates this suite to ZimmCountryLanguageMismatch's own contract — same technique
// zimmSubscribeSection/index.test.tsx uses. The default mock returns the fallback unmodified:
// real interpolation isn't needed to prove "this variant renders its own heading/body/CTA
// content" (the raw fallback string, `{token}` placeholders included, is a perfectly good
// assertion target) — the explicit toHaveBeenCalledWith assertions below separately prove the
// values object each call receives.
vi.mock('app/hooks/useUiCopy', () => ({
  useUiCopy: vi.fn(),
}));

const mockUseUiCopy = vi.mocked(useUiCopy);
const mockT = vi.fn((_key: string, fallback: string) => fallback);

const LOCATION_HEADING_FALLBACK = "Looks like you're {inCountry}";
const LOCATION_BODY_FALLBACK =
  "You're currently shopping on {currentStore}. Switch to {targetStore} for local pricing, currency and shipping options.";
const LOCATION_SWITCH_CTA_FALLBACK = 'Switch to {targetStore}';
const LOCATION_STAY_CTA_FALLBACK = 'Stay on {currentStore}';

const LANGUAGE_HEADING_FALLBACK = 'Welcome to Zimmermann Europe';
const LANGUAGE_BODY_FALLBACK =
  "Welcome to Zimmermann Europe. We noticed you're {inCountry}, would you like to view our site {inLanguage}?";
const LANGUAGE_SWITCH_CTA_FALLBACK = 'View {inLanguage}';
const LANGUAGE_STAY_CTA_FALLBACK = 'Continue {inCurrentLanguage}';

function makeLocationProps(
  overrides: Partial<ZimmCountryLanguageMismatchLocationProps> = {},
): ZimmCountryLanguageMismatchLocationProps {
  return {
    variant: 'location',
    isOpen: true,
    onDismiss: vi.fn(),
    inCountry: 'in Germany',
    currentStore: 'Zimmermann Australia',
    targetStore: 'Zimmermann Germany',
    target: { siteAlias: 'ZimmermannEUde', localeAlias: 'de-DE' },
    onRedirect: vi.fn(),
    ...overrides,
  };
}

function makeLanguageProps(
  overrides: Partial<ZimmCountryLanguageMismatchLanguageProps> = {},
): ZimmCountryLanguageMismatchLanguageProps {
  return {
    variant: 'language',
    isOpen: true,
    onDismiss: vi.fn(),
    inCountry: 'in France',
    inLanguage: 'in French',
    inCurrentLanguage: 'in English',
    target: 'fr-FR-Weird-Casing',
    onSwitchLanguage: vi.fn(),
    ...overrides,
  };
}

describe('ZimmCountryLanguageMismatch', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockT.mockImplementation((_key: string, fallback: string) => fallback);
    mockUseUiCopy.mockReturnValue({ t: mockT, isLoading: false });
  });

  describe('location variant', () => {
    test('renders its own heading, body, and CTA content', () => {
      render(<ZimmCountryLanguageMismatch {...makeLocationProps()} />);

      expect(screen.getByRole('heading', { name: LOCATION_HEADING_FALLBACK, level: 2 })).toBeInTheDocument();
      expect(screen.getByText(LOCATION_BODY_FALLBACK)).toBeInTheDocument();
      expect(screen.getByRole('button', { name: LOCATION_SWITCH_CTA_FALLBACK })).toBeInTheDocument();
      expect(screen.getByRole('button', { name: LOCATION_STAY_CTA_FALLBACK })).toBeInTheDocument();
    });

    test('the dialog is labelled by the rendered heading', () => {
      render(<ZimmCountryLanguageMismatch {...makeLocationProps()} />);

      expect(screen.getByRole('dialog', { name: LOCATION_HEADING_FALLBACK })).toBeInTheDocument();
    });

    test('passes the location copy keys and display values to t()', () => {
      render(<ZimmCountryLanguageMismatch {...makeLocationProps()} />);

      expect(mockT).toHaveBeenCalledWith(
        'regional.locationPrompt.heading',
        LOCATION_HEADING_FALLBACK,
        expect.objectContaining({ inCountry: 'in Germany' }),
      );
      expect(mockT).toHaveBeenCalledWith(
        'regional.locationPrompt.body',
        LOCATION_BODY_FALLBACK,
        expect.objectContaining({ currentStore: 'Zimmermann Australia', targetStore: 'Zimmermann Germany' }),
      );
      expect(mockT).toHaveBeenCalledWith(
        'regional.locationPrompt.cta.switch',
        LOCATION_SWITCH_CTA_FALLBACK,
        expect.objectContaining({ targetStore: 'Zimmermann Germany' }),
      );
      expect(mockT).toHaveBeenCalledWith(
        'regional.locationPrompt.cta.stay',
        LOCATION_STAY_CTA_FALLBACK,
        expect.objectContaining({ currentStore: 'Zimmermann Australia' }),
      );
    });
  });

  describe('language variant', () => {
    test('renders its own heading, body, and CTA content', () => {
      render(<ZimmCountryLanguageMismatch {...makeLanguageProps()} />);

      expect(screen.getByRole('heading', { name: LANGUAGE_HEADING_FALLBACK, level: 2 })).toBeInTheDocument();
      expect(screen.getByText(LANGUAGE_BODY_FALLBACK)).toBeInTheDocument();
      expect(screen.getByRole('button', { name: LANGUAGE_SWITCH_CTA_FALLBACK })).toBeInTheDocument();
      expect(screen.getByRole('button', { name: LANGUAGE_STAY_CTA_FALLBACK })).toBeInTheDocument();
    });

    test('the dialog is labelled by the rendered heading', () => {
      render(<ZimmCountryLanguageMismatch {...makeLanguageProps()} />);

      expect(screen.getByRole('dialog', { name: LANGUAGE_HEADING_FALLBACK })).toBeInTheDocument();
    });

    test('passes the language copy keys and display values to t()', () => {
      render(<ZimmCountryLanguageMismatch {...makeLanguageProps()} />);

      expect(mockT).toHaveBeenCalledWith(
        'regional.languagePrompt.heading',
        LANGUAGE_HEADING_FALLBACK,
        expect.objectContaining({ inCountry: 'in France' }),
      );
      expect(mockT).toHaveBeenCalledWith(
        'regional.languagePrompt.body',
        LANGUAGE_BODY_FALLBACK,
        expect.objectContaining({ inCountry: 'in France', inLanguage: 'in French' }),
      );
      expect(mockT).toHaveBeenCalledWith(
        'regional.languagePrompt.cta.switch',
        LANGUAGE_SWITCH_CTA_FALLBACK,
        expect.objectContaining({ inLanguage: 'in French' }),
      );
      expect(mockT).toHaveBeenCalledWith(
        'regional.languagePrompt.cta.stay',
        LANGUAGE_STAY_CTA_FALLBACK,
        expect.objectContaining({ inCurrentLanguage: 'in English' }),
      );
    });
  });

  describe('dismiss wiring', () => {
    test('onDismiss fires when the drawer reports close (backdrop/X/Esc, via ZimmDrawer onClose)', async () => {
      const onDismiss = vi.fn();
      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ onDismiss })} />);

      await userEvent.click(screen.getByRole('button', { name: 'mock-close' }));

      expect(onDismiss).toHaveBeenCalledTimes(1);
    });

    test('onDismiss fires when the stay CTA is clicked', async () => {
      const onDismiss = vi.fn();
      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ onDismiss })} />);

      await userEvent.click(screen.getByRole('button', { name: LOCATION_STAY_CTA_FALLBACK }));

      expect(onDismiss).toHaveBeenCalledTimes(1);
    });

    test('the stay CTA does not also fire onRedirect', async () => {
      const onDismiss = vi.fn();
      const onRedirect = vi.fn();
      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ onDismiss, onRedirect })} />);

      await userEvent.click(screen.getByRole('button', { name: LOCATION_STAY_CTA_FALLBACK }));

      expect(onDismiss).toHaveBeenCalledTimes(1);
      expect(onRedirect).not.toHaveBeenCalled();
    });
  });

  describe('act-CTA callback wiring', () => {
    test('onRedirect fires with the exact target value, unmodified', async () => {
      const target = { siteAlias: 'ZimmermannEUde', localeAlias: 'de-DE' };
      const onRedirect = vi.fn();
      render(<ZimmCountryLanguageMismatch {...makeLocationProps({ target, onRedirect })} />);

      await userEvent.click(screen.getByRole('button', { name: LOCATION_SWITCH_CTA_FALLBACK }));

      expect(onRedirect).toHaveBeenCalledTimes(1);
      expect(onRedirect).toHaveBeenCalledWith(target);
      expect(onRedirect.mock.calls[0][0]).toStrictEqual(target);
    });

    test('onSwitchLanguage fires with the exact target value, unmodified', async () => {
      const target = 'fr-FR-Weird-Casing';
      const onSwitchLanguage = vi.fn();
      render(<ZimmCountryLanguageMismatch {...makeLanguageProps({ target, onSwitchLanguage })} />);

      await userEvent.click(screen.getByRole('button', { name: LANGUAGE_SWITCH_CTA_FALLBACK }));

      expect(onSwitchLanguage).toHaveBeenCalledTimes(1);
      expect(onSwitchLanguage).toHaveBeenCalledWith(target);
    });
  });
});

