import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmDrawer } from './index';
import { useUiCopy } from 'app/hooks/useUiCopy';

// TEMPORARY SCRATCH PROBE — not part of the real suite. Verifies the exact resolved
// aria-labelledby attribute value directly, as a stronger empirical supplement to
// index.test.tsx's accessible-name (getByRole name:) assertion. Deleted after this
// verification step.

vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
vi.mock('app/hooks/useUiCopy', () => ({ useUiCopy: vi.fn() }));

const mockUseUiCopy = vi.mocked(useUiCopy);
const mockT = vi.fn((_key: string, fallback: string) => fallback);

const renderDrawer = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);

describe('SCRATCH PROBE — ZimmDrawer aria-labelledby raw attribute resolution', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockT.mockImplementation((_key: string, fallback: string) => fallback);
    mockUseUiCopy.mockReturnValue({ t: mockT, isLoading: false });
  });

  test('dialog aria-labelledby attribute value is exactly the external id, and resolves to the external element, not the empty title span', () => {
    renderDrawer(
      <div>
        <h2 id="ext-label-probe">Probe external heading</h2>
        <ZimmDrawer isOpen onClose={vi.fn()} size="prompt" labelledBy="ext-label-probe" boxedHeader>
          <p>Body content</p>
        </ZimmDrawer>
      </div>,
    );

    const dialog = screen.getByRole('dialog');

    // Direct attribute assertion — the raw wire value, not the computed accessible name.
    expect(dialog).toHaveAttribute('aria-labelledby', 'ext-label-probe');

    // The empty title span must NOT carry any id at all (so it could never be a target of
    // aria-labelledby even if some other bug pointed at it).
    const closeButton = screen.getByRole('button', { name: 'Close' });
    const headerBox = closeButton.parentElement;
    const titleSpan = headerBox?.children[0];
    expect(titleSpan?.tagName).toBe('SPAN');
    expect(titleSpan).not.toHaveAttribute('id');

    // Resolve the id referenced by aria-labelledby back to a real DOM node, and confirm it is
    // the external <h2>, not the title span — the strongest possible proof the wiring points at
    // the right element, not just that the attribute string happens to look right.
    const labelledById = dialog.getAttribute('aria-labelledby');
    expect(labelledById).toBeTruthy();
    const referencedNode = labelledById ? document.getElementById(labelledById) : null;
    expect(referencedNode).not.toBeNull();
    expect(referencedNode).toHaveTextContent('Probe external heading');
    expect(referencedNode?.tagName).toBe('H2');
    expect(referencedNode).not.toBe(titleSpan);
  });
});

